// A night street generated by chance, walked by scrolling, and alive while you watch.
//   Skyline:        fractal noise heights
//   Office windows: two-state Markov chain per window; more go dark as the night gets later
//   Lanterns, blur of lights, shooting stars: Poisson processes
//   Depth of field: far and near layers are softened, like a fast lens at night
"use strict";
(function () {
  var REDUCED = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var MOBILE = window.matchMedia("(max-width: 640px)").matches;
  var DPR = Math.min(window.devicePixelRatio || 1, MOBILE ? 2 : 1.5);
  var world = document.getElementById("world");
  var sky = document.getElementById("sky");
  var life = document.getElementById("life");
  var lg = life.getContext("2d");
  var bar = document.getElementById("bar");
  var progressEl = document.getElementById("progress");
  var seedEl = document.getElementById("seed");
  var chapters = Array.prototype.slice.call(document.querySelectorAll(".chapter"));

  // ---------- randomness ----------
  function RNG(seed) {
    var s = seed >>> 0;
    return function () {
      s = (s + 0x6d2b79f5) >>> 0;
      var t = s;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function valueNoise(r) {
    var pts = [];
    for (var i = 0; i < 257; i++) pts.push(r());
    return function (x) {
      x = ((x % 256) + 256) % 256;
      var i = Math.floor(x), f = x - i, s = f * f * (3 - 2 * f);
      return pts[i] * (1 - s) + pts[i + 1] * s;
    };
  }
  function fbm(n, x) {
    var a = 0.5, f = 1, s = 0;
    for (var o = 0; o < 4; o++) { s += a * n(x * f); a *= 0.5; f *= 2; }
    return s / 0.9375;
  }
  function poisson(r, lambda) {
    var L = Math.exp(-lambda), k = 0, p = 1;
    do { k++; p *= r(); } while (p > L);
    return k - 1;
  }
  function expo(rate) { return -Math.log(1 - Math.random()) / rate; }
  function pick(r, arr) { return arr[Math.floor(r() * arr.length)]; }
  function hexA(hex, a) {
    var n = parseInt(hex.slice(1), 16);
    return "rgba(" + (n >> 16) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a.toFixed(3) + ")";
  }

  var NEON = ["#ffb347", "#ff5d73", "#4fd1ff", "#ffd36b", "#ff8a5c"];
  var WARM = ["#ffd9a0", "#ffc978", "#ffe7c2"];
  var COOL = ["#9fdcff", "#c8ecff"];

  // Does canvas ctx.filter actually blur here? (Safari may ignore it.)
  var CANVAS_BLUR = (function () {
    try {
      var a = document.createElement("canvas"); a.width = a.height = 9;
      var g = a.getContext("2d");
      g.filter = "blur(2px)";
      g.fillStyle = "#fff"; g.fillRect(4, 4, 1, 1);
      return g.getImageData(2, 4, 1, 1).data[3] > 0;
    } catch (e) { return false; }
  })();

  // ---------- layers ----------
  function makeLayer(depth, vw, vh, blur) {
    var w = Math.ceil(vw * (1 + depth * 2.2));
    var c = document.createElement("canvas");
    c.width = Math.ceil(w * DPR); c.height = Math.ceil(vh * DPR);
    c.style.width = w + "px"; c.style.height = vh + "px";
    var g = c.getContext("2d");
    g.scale(DPR, DPR);
    // paint into a scratch canvas first, then composite with blur
    var scratch = document.createElement("canvas");
    scratch.width = c.width; scratch.height = c.height;
    var sg = scratch.getContext("2d");
    sg.scale(DPR, DPR);
    var el = document.createElement("div");
    el.className = "layer";
    el.appendChild(c);
    return { el: el, c: c, g: g, sg: sg, scratch: scratch, w: w, h: vh, depth: depth, blur: blur, dx: 0, dy: 0 };
  }
  function commit(L) {
    L.g.save();
    L.g.setTransform(1, 0, 0, 1, 0, 0);
    if (L.blur && CANVAS_BLUR) L.g.filter = "blur(" + (L.blur * DPR).toFixed(1) + "px)";
    L.g.drawImage(L.scratch, 0, 0);
    L.g.restore();
    if (L.blur && !CANVAS_BLUR) L.c.style.filter = "blur(" + L.blur + "px)";
    L.scratch = null; L.sg = null;
  }

  function paintStars(g, L, r) {
    var n = poisson(r, L.w / (MOBILE ? 10 : 14));
    for (var i = 0; i < n; i++) {
      g.fillStyle = "rgba(241,236,228," + (0.25 + r() * 0.5).toFixed(2) + ")";
      var s = r() < 0.1 ? 1.6 : 1;
      g.fillRect(r() * L.w, r() * L.h * 0.45, s, s);
    }
  }

  function softTop(g, x, top, bw, color) {
    // a faint rim of city glow along the roofline
    var rim = g.createLinearGradient(0, top, 0, top + 10);
    rim.addColorStop(0, color); rim.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = rim; g.fillRect(x, top, bw, 10);
  }

  function paintSkyline(L, r, noise) {
    var g = L.sg, x = 0;
    while (x < L.w) {
      var bw = 30 + r() * 70;
      var bh = L.h * (0.2 + 0.34 * fbm(noise, x / 420));
      g.fillStyle = "#1a1f3c";
      g.fillRect(x, L.h - bh, bw + 1, bh);
      for (var wy = L.h - bh + 8; wy < L.h - 10; wy += 9) {
        for (var wx = x + 5; wx < x + bw - 5; wx += 7) {
          if (r() < 0.1) { g.fillStyle = "rgba(255,217,160,0.4)"; g.fillRect(wx, wy, 2, 3); }
        }
      }
      softTop(g, x, L.h - bh, bw, "rgba(150,120,200,0.25)");
      x += bw;
    }
    // haze at the base of the far city
    var hz = g.createLinearGradient(0, L.h * 0.55, 0, L.h);
    hz.addColorStop(0, "rgba(90,47,76,0)"); hz.addColorStop(1, "rgba(90,47,76,0.45)");
    g.fillStyle = hz; g.fillRect(0, L.h * 0.55, L.w, L.h * 0.45);
  }

  var windows = [];   // dynamic office lights on the tower layer
  var beacons = [];   // blinking antenna lights, in tower-layer coordinates

  function paintTowers(L, r, noise) {
    var g = L.sg, x = -20;
    while (x < L.w) {
      var bw = 60 + r() * 110;
      var bh = L.h * (0.3 + 0.42 * fbm(noise, x / 300 + 40));
      var top = L.h - bh;
      var grad = g.createLinearGradient(0, top, 0, L.h);
      grad.addColorStop(0, "#141a36"); grad.addColorStop(1, "#0b0f22");
      g.fillStyle = grad;
      // a setback crown on some towers
      if (r() < 0.4) {
        var cw = bw * (0.45 + r() * 0.3), ch = 14 + r() * 26;
        g.fillRect(x + (bw - cw) / 2, top - ch, cw, ch + 1);
        softTop(g, x + (bw - cw) / 2, top - ch, cw, "rgba(120,140,220,0.22)");
      }
      g.fillRect(x, top, bw, bh);
      softTop(g, x, top, bw, "rgba(120,140,220,0.18)");
      var p = 0.22 + r() * 0.3, cool = r() < 0.3;
      for (var wy = top + 12; wy < L.h - 16; wy += 14) {
        for (var wx = x + 8; wx < x + bw - 10; wx += 11) {
          windows.push({
            x: wx, y: wy, lit: r() < p,
            color: pick(r, cool ? COOL : WARM), alpha: 0.45 + r() * 0.45,
            off: (function (yy) { var t = (yy - top) / Math.max(1, bh); return t < 0.5 ? "#12172f" : "#0e1328"; })(wy)
          });
        }
      }
      if (r() < 0.35) {
        var ax = x + bw * (0.3 + r() * 0.4);
        g.fillStyle = "#141a36"; g.fillRect(ax, top - 24, 2, 24);
        beacons.push({ x: ax + 1, y: top - 25, phase: r() * 6.28, period: 1.4 + r() * 1.4 });
      }
      x += bw + r() * 14;
    }
  }
  function drawWindow(L, w) {
    var g = L.g;
    if (w.lit) { g.globalAlpha = w.alpha; g.fillStyle = w.color; }
    else { g.globalAlpha = 1; g.fillStyle = w.off; }
    g.fillRect(w.x, w.y, 5, 7);
    g.globalAlpha = 1;
  }

  function glow(g, color, blur, fn) { g.save(); g.shadowColor = color; g.shadowBlur = blur; fn(); g.restore(); }

  function paintStreet(L, r, noise) {
    var g = L.sg, x = -10;
    while (x < L.w) {
      var bw = 90 + r() * 140;
      var bh = L.h * (0.2 + 0.2 * fbm(noise, x / 200 + 90));
      var top = L.h - bh;
      g.fillStyle = "#090c1a";
      g.fillRect(x, top, bw, bh);
      var sw = L.h * 0.07;
      var wg = g.createLinearGradient(0, L.h - sw, 0, L.h);
      wg.addColorStop(0, "rgba(255,201,120,0.0)"); wg.addColorStop(1, "rgba(255,201,120,0.3)");
      g.fillStyle = wg; g.fillRect(x + 6, L.h - sw, bw - 12, sw);
      if (r() < 0.7) {
        var col = pick(r, NEON), sx = x + 10 + r() * (bw - 40), sh = 50 + r() * 110, sy = top - sh * 0.4;
        glow(g, col, 22, function () {
          g.strokeStyle = col; g.lineWidth = 2.2;
          g.strokeRect(sx, sy, 22, sh);
          for (var k = sy + 12; k < sy + sh - 8; k += 14) { g.fillStyle = col; g.fillRect(sx + 7, k, 8, 6); }
        });
      }
      var n = poisson(r, 3.2);
      var ly = top + 10 + r() * 30;
      for (var i = 0; i < n; i++) {
        var lx = x + 14 + i * 22;
        if (lx > x + bw - 10) break;
        glow(g, "#ffd9a0", 18, function () {
          g.fillStyle = "#ffe7c2"; g.beginPath(); g.arc(lx, ly, 6, 0, Math.PI * 2); g.fill();
        });
      }
      x += bw + 6;
    }
  }

  function paintBokeh(L, r) {
    var g = L.sg;
    g.globalCompositeOperation = "lighter";
    var n = poisson(r, L.w / (MOBILE ? 45 : 70));
    for (var i = 0; i < n; i++) {
      var cx = r() * L.w, cy = L.h * (0.12 + r() * 0.85), rad = (MOBILE ? 16 : 18) + r() * 70;
      var col = pick(r, NEON.concat(WARM));
      // a lens disc: flat body, brighter rim, like out-of-focus highlights in a photo
      var rg = g.createRadialGradient(cx, cy, 0, cx, cy, rad);
      var a = 0.12 + r() * 0.14;
      rg.addColorStop(0, hexA(col, a * 0.8));
      rg.addColorStop(0.82, hexA(col, a));
      rg.addColorStop(0.95, hexA(col, a * 1.5));
      rg.addColorStop(1, hexA(col, 0));
      g.fillStyle = rg; g.beginPath(); g.arc(cx, cy, rad, 0, Math.PI * 2); g.fill();
    }
    g.globalCompositeOperation = "source-over";
  }

  var layers = [];
  var seed = 0;
  var towerLayer = null;

  function build(newSeed) {
    seed = newSeed >>> 0;
    var r = RNG(seed);
    var noise = valueNoise(r);
    var vw = window.innerWidth, vh = window.innerHeight;
    world.innerHTML = "";
    windows = []; beacons = [];
    layers = [
      makeLayer(0.12, vw, vh, 2.2),   // far: soft
      makeLayer(0.35, vw, vh, 0.7),   // towers: nearly in focus
      makeLayer(0.7, vw, vh, 1.6),    // street: soft
      makeLayer(1.15, vw, vh, 3)      // lens blur in front
    ];
    paintStars(layers[0].g, layers[0], r);     // stars stay sharp
    paintSkyline(layers[0], r, noise);
    paintTowers(layers[1], r, noise);
    paintStreet(layers[2], r, noise);
    paintBokeh(layers[3], r);
    layers.forEach(commit);
    towerLayer = layers[1];
    windows.forEach(function (w) { drawWindow(towerLayer, w); });
    layers.forEach(function (L) { world.appendChild(L.el); });
    if (seedEl) seedEl.textContent = "Street no. " + seed.toString(36) + ".";
    sizeLife();
    frame();
  }

  // ---------- life: office lights, beacons, shooting stars ----------
  function sizeLife() {
    life.width = Math.ceil(window.innerWidth * DPR);
    life.height = Math.ceil(window.innerHeight * DPR);
    lg.setTransform(DPR, 0, 0, DPR, 0, 0);
  }

  var progress = 0;
  var stars = [];
  var nextStar = REDUCED ? Infinity : expo(1 / 6);

  function stepWindows(dt) {
    if (REDUCED || !windows.length) return;
    // Each window is a two-state Markov chain. Later in the walk, offices empty out:
    // the switch-off rate rises and the switch-on rate falls.
    var on = 0.012 * (1 - 0.6 * progress), off = 0.012 * (0.6 + 1.4 * progress);
    var expected = windows.length * (on + off) * 0.5 * dt;
    var n = poisson(Math.random, Math.min(expected, 40));
    for (var i = 0; i < n; i++) {
      var w = windows[Math.floor(Math.random() * windows.length)];
      var flip = w.lit ? Math.random() < off / (on + off) : Math.random() < on / (on + off);
      if (flip) { w.lit = !w.lit; drawWindow(towerLayer, w); }
    }
  }

  function spawnStar() {
    var vw = window.innerWidth, vh = window.innerHeight;
    var dir = Math.random() < 0.5 ? -1 : 1;
    stars.push({
      x: vw * (0.15 + Math.random() * 0.7), y: vh * (0.04 + Math.random() * 0.26),
      vx: dir * (420 + Math.random() * 380), vy: 140 + Math.random() * 160,
      len: 90 + Math.random() * 140, life: 0, ttl: 0.7 + Math.random() * 0.5
    });
  }

  function drawLife(dt, t) {
    lg.clearRect(0, 0, window.innerWidth, window.innerHeight);
    // beacons ride along with the tower layer
    if (towerLayer) {
      for (var i = 0; i < beacons.length; i++) {
        var b = beacons[i];
        var x = b.x + towerLayer.dx, y = b.y + towerLayer.dy;
        if (x < -10 || x > window.innerWidth + 10) continue;
        var k = REDUCED ? 0.8 : Math.pow(Math.max(0, Math.sin((t / b.period) * 6.283 + b.phase)), 8);
        var rg = lg.createRadialGradient(x, y, 0, x, y, 10);
        rg.addColorStop(0, "rgba(255,93,115," + (0.25 + 0.75 * k).toFixed(2) + ")");
        rg.addColorStop(1, "rgba(255,93,115,0)");
        lg.fillStyle = rg; lg.beginPath(); lg.arc(x, y, 10, 0, 6.283); lg.fill();
      }
    }
    // shooting stars
    for (var j = stars.length - 1; j >= 0; j--) {
      var s = stars[j];
      s.life += dt; s.x += s.vx * dt; s.y += s.vy * dt;
      if (s.life > s.ttl) { stars.splice(j, 1); continue; }
      var fade = Math.sin(Math.PI * (s.life / s.ttl));
      var sp = Math.hypot(s.vx, s.vy), ux = s.vx / sp, uy = s.vy / sp;
      var tx = s.x - ux * s.len, ty = s.y - uy * s.len;
      var gr = lg.createLinearGradient(s.x, s.y, tx, ty);
      gr.addColorStop(0, "rgba(255,244,220," + (0.95 * fade).toFixed(2) + ")");
      gr.addColorStop(1, "rgba(255,244,220,0)");
      lg.strokeStyle = gr; lg.lineWidth = 1.6; lg.lineCap = "round";
      lg.beginPath(); lg.moveTo(s.x, s.y); lg.lineTo(tx, ty); lg.stroke();
    }
  }

  var last = performance.now(), elapsed = 0;
  function loop(now) {
    var dt = Math.min(0.1, (now - last) / 1000);
    last = now; elapsed += dt;
    if (!document.hidden) {
      stepWindows(dt);
      nextStar -= dt;
      if (nextStar <= 0) {
        spawnStar();
        nextStar = expo(1 / (progress > 0.5 ? 4 : 7)); // more of them deeper into the night
      }
      drawLife(dt, elapsed);
    }
    requestAnimationFrame(loop);
  }

  // ---------- chapters and progress ----------
  var ticks = [];
  function setupProgress() {
    chapters.forEach(function (ch) {
      var a = document.createElement("a");
      a.className = "tick";
      a.href = "#" + ch.id;
      a.textContent = ch.getAttribute("data-name");
      progressEl.appendChild(a);
      ticks.push(a);
    });
    placeTicks();
  }
  function placeTicks() {
    var max = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
    ticks.forEach(function (t, i) {
      var c = chapters[i], mid = c.offsetTop + c.offsetHeight / 2 - window.innerHeight / 2;
      t.style.left = (Math.min(1, Math.max(0, mid / max)) * 100).toFixed(2) + "%";
    });
  }

  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) { if (e.isIntersecting) e.target.classList.add("on"); });
    }, { threshold: 0.12 });
    chapters.forEach(function (c) { io.observe(c); });
  } else {
    chapters.forEach(function (c) { c.classList.add("on"); });
  }

  function mix(a, b, t) {
    var x = parseInt(a.slice(1), 16), y = parseInt(b.slice(1), 16);
    var r = Math.round((x >> 16) + ((y >> 16) - (x >> 16)) * t);
    var gg = Math.round(((x >> 8) & 255) + (((y >> 8) & 255) - ((x >> 8) & 255)) * t);
    var bl = Math.round((x & 255) + ((y & 255) - (x & 255)) * t);
    return "rgb(" + r + "," + gg + "," + bl + ")";
  }

  var ticking = false;
  function frame() {
    ticking = false;
    var vw = window.innerWidth;
    var max = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
    var p = Math.min(1, Math.max(0, window.scrollY / max));
    progress = p;
    var walk = REDUCED ? 0.18 : p;
    layers.forEach(function (L) {
      L.dx = -walk * (L.w - vw);
      L.dy = REDUCED ? 0 : (1 - walk) * L.depth * 26;
      L.el.style.transform = "translate3d(" + L.dx.toFixed(1) + "px," + L.dy.toFixed(1) + "px,0)";
    });
    sky.style.setProperty("--sky-top", mix("#1b1844", "#05070f", p));
    sky.style.setProperty("--sky-mid", mix("#43285a", "#121230", p));
    sky.style.setProperty("--sky-low", mix("#6a3352", "#2a1a3a", p));
    if (bar) bar.style.width = (p * 100).toFixed(2) + "%";
    var active = 0;
    chapters.forEach(function (c, i) { if (c.offsetTop <= window.scrollY + window.innerHeight * 0.5) active = i; });
    ticks.forEach(function (t, i) { t.classList.toggle("on", i === active); });
  }
  function onScroll() { if (!ticking) { ticking = true; requestAnimationFrame(frame); } }

  var resizeTimer, lastW = window.innerWidth;
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", function () {
    // mobile browsers resize the viewport while scrolling (address bar); only rebuild on width changes
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      if (window.innerWidth !== lastW) { lastW = window.innerWidth; build(seed); }
      else { sizeLife(); }
      placeTicks(); frame();
    }, 200);
  });

  var reroll = document.getElementById("reroll");
  if (reroll) reroll.addEventListener("click", function () { build((Math.random() * 4294967296) >>> 0); });

  setupProgress();
  build((Math.random() * 4294967296) >>> 0);
  requestAnimationFrame(loop);
})();
